/**
 * Parity tests for the Deno copy of the client's balance maths.
 *
 *  - unclaimedParityCases.json is the client's own shared fixture (also run by
 *    src/features/expenses/lib/balances.test.ts and the Postgres guard script).
 *  - balancesParityCases.json was GENERATED by running the client functions
 *    (computeBalances, withMoneyParticipants, computePairwiseBreakdown) on the
 *    same inputs; the expected values are the client's output, not hand-written.
 * (ownClaimParityCases.json covers claimMath.claimAmountMinor, which is not part
 * of this mirror and not used by the chat reads.)
 *
 * Run: npx -y deno test --no-lock --node-modules-dir=none supabase/functions/_shared/money/balances.test.ts
 */
import { assertEquals } from 'jsr:@std/assert@1'
import { computeBalances, findFreezeBlockingReceipts, withMoneyParticipants } from './balances.ts'
import type { ExpenseWithDetails } from './balanceTypes.ts'
import parityCases from './balancesParityCases.json' with { type: 'json' }

// deno-lint-ignore no-explicit-any
type Any = any

const unclaimed = JSON.parse(await Deno.readTextFile(new URL('../../../../src/features/expenses/lib/unclaimedParityCases.json', import.meta.url)))

function receipt(amount: number, currency: string, fx: number | null, lines: Any[], claims: Any[]): ExpenseWithDetails {
  return {
    id: 'r', description: 'r', amount, currency, fx_rate: fx, paid_by: 'alice', payment_date: '2026-08-01', ai_parsed: true, status: 'pending_allocation',
    splits: [], allocation_link: null, line_items: lines, claims,
  } as unknown as ExpenseWithDetails
}

for (const c of unclaimed.cases as Any[]) {
  Deno.test(`freeze blocking agrees with the server guard: ${c.name}`, () => {
    const lines = c.lines.map((l: Any, i: number) => ({ id: `l${i}`, expense_id: 'e', line_number: 1, name_original: `l${i}`, name_english: null, quantity: l[0], unit_price: l[1] / l[0], subtotal: l[1], total_amount: l[1] }))
    const claims = c.lines.flatMap((l: Any, i: number) => l[2].map(([q, a]: number[], k: number) => ({ expense_id: 'e', line_item_id: `l${i}`, user_id: `u${k}`, quantity_claimed: q, amount_owed: a })))
    const blocking = findFreezeBlockingReceipts([receipt(c.amount, c.currency, c.fx, lines, claims)], c.base)
    assertEquals(blocking.length === 0 ? 0 : blocking[0].unclaimedOwnMinor, c.blockedOwnMinor)
  })
}

for (const s of parityCases.scenarios as Any[]) {
  Deno.test(`computeBalances matches the client: ${s.name}`, () => {
    const ids = withMoneyParticipants(s.roster, s.expenses, s.settlements, s.base, s.carryovers)
    assertEquals(ids, s.expected.ledgerIds)
    const r = computeBalances(s.expenses, s.settlements, ids, s.base, s.carryovers)
    assertEquals(JSON.parse(JSON.stringify(r.balances)), s.expected.balances)
    assertEquals(r.groupTotalMinor, s.expected.groupTotalMinor)
    assertEquals(r.expensesMissingRate, s.expected.expensesMissingRate)
    assertEquals(r.unclaimedTotalMinor, s.expected.unclaimedTotalMinor)
    assertEquals(r.pendingUnclaimedTotalMinor, s.expected.pendingUnclaimedTotalMinor)
    assertEquals(r.unclaimedReceipts.map((x) => x.expenseId), s.expected.unclaimedReceiptIds)
    // The ledger always sums to zero.
    assertEquals(r.balances.reduce((a, b) => a + b.netBalanceMinor, 0), 0)
  })
}

Deno.test('suggested and marked-paid settlements never move a balance', () => {
  const s = (parityCases.scenarios as Any[]).find((x) => x.name.startsWith('confirmed, marked paid'))
  const ids = withMoneyParticipants(s.roster, s.expenses, s.settlements, s.base, s.carryovers)
  const r = computeBalances(s.expenses, s.settlements, ids, s.base, s.carryovers)
  const cara = r.balances.find((b) => b.userId === 'cara')!
  assertEquals(cara.settlementsPaidMinor, 0)
  const bob = r.balances.find((b) => b.userId === 'bob')!
  assertEquals(bob.settlementsPaidMinor, 1000)
})
